/* FieldModelHeader/tri/quad offsets are the original on-disc scalar layout,
 * not sizeof a host struct with process pointers. */
static uint32_t model_get(const unsigned char*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint16_t model_half(const unsigned char*p){return(uint16_t)(p[0]|p[1]<<8);}
static void model_put(unsigned char*p,uint32_t v){for(unsigned j=0;j<4;j++)p[j]=(unsigned char)(v>>(j*8));}
static void model_sethalf(unsigned char*p,uint16_t v){p[0]=(unsigned char)v;p[1]=(unsigned char)(v>>8);}
typedef struct ModelShape{uint32_t triangles,quads,colours,colourOffset,faceEnd,extent;uint16_t counts[4];}ModelShape;
static int model_shape(const unsigned char*p,size_t available,ModelShape*s){if(!p||!s||available<16)return 0;memset(s,0,sizeof*s);for(unsigned j=0;j<4;j++)s->counts[j]=model_half(p+j*2);s->triangles=(uint32_t)s->counts[0]+s->counts[1];s->quads=(uint32_t)s->counts[2]+s->counts[3];s->colours=model_half(p+10);s->colourOffset=model_half(p+8);if(s->triangles+s->quads>256||s->colours>256)return 0;s->faceEnd=16+s->triangles*12+s->quads*16;if(s->faceEnd>available||s->colourOffset%4||s->colourOffset<s->faceEnd||(size_t)s->colourOffset+s->colours*4>available)return 0;s->extent=s->colourOffset+s->colours*4;if(s->extent<s->faceEnd)s->extent=s->faceEnd;
 for(unsigned kind=0;kind<2;kind++){unsigned count=kind?s->quads:s->triangles,width=kind?4:3,stride=kind?16:12,base=16+(kind?s->triangles*12:0),flat=kind?s->counts[2]:s->counts[0];for(unsigned j=0;j<count;j++)for(unsigned v=0;v<width;v++){unsigned offset=model_half(p+base+j*stride+v*2);if(offset%2||offset<s->faceEnd||offset>available||8u>available-offset)return 0;if(offset<s->colourOffset+s->colours*4&&offset+8>s->colourOffset)return 0;if(offset+8>s->extent)s->extent=offset+8;if(j>=flat||v==0){unsigned colour=model_half(p+offset+6);if(colour%4||colour<s->colourOffset||colour-s->colourOffset>=s->colours*4)return 0;}}}return s->extent<=available;
}
static int model_mutable(const ModelShape*s,size_t offset){if(offset>=12&&offset<16)return 1;if(offset>=s->colourOffset&&offset<s->colourOffset+s->colours*4)return 1;if(offset>=16&&offset<s->faceEnd){offset-=16;if(offset<s->triangles*12)return offset%12>=6;offset-=s->triangles*12;return offset%16>=8;}return 0;}
static uint32_t model_crc(const unsigned char*p,const ModelShape*s){uint32_t crc=~0u;for(size_t j=0;j<s->extent;j++){unsigned v=model_mutable(s,j)?0:p[j];crc^=v;for(unsigned k=0;k<8;k++)crc=(crc>>1)^(0xedb88320u&-(int32_t)(crc&1));}return ~crc;}
static int model_walk(unsigned char*p,size_t available,const unsigned char*in,unsigned char*out,int apply){ModelShape s;if(!model_shape(p,available,&s))return 0;size_t at=40;uint32_t identity[7]={s.extent,model_crc(p,&s),s.triangles,s.quads,s.colourOffset,s.colours,s.faceEnd};if(out){memset(out,0,PE_STATE_FIELD_MODEL_BYTES);memcpy(out,"PEFMOD01",8);for(unsigned j=0;j<7;j++)model_put(out+8+j*4,identity[j]);}else{if(memcmp(in,"PEFMOD01",8)||model_get(in+36))return 0;for(unsigned j=0;j<7;j++)if(model_get(in+8+j*4)!=identity[j])return 0;}
#define HALF(offset) do{uint32_t value=out?model_half(p+(offset)):model_get(in+at);if(value>65535)return 0;if(out)model_put(out+at,value);else if(apply)model_sethalf(p+(offset),(uint16_t)value);at+=4;}while(0)
 HALF(12);HALF(14);for(unsigned j=0;j<s.triangles;j++)for(unsigned v=0;v<3;v++)HALF(16+j*12+6+v*2);for(unsigned j=0;j<s.quads;j++)for(unsigned v=0;v<4;v++)HALF(16+s.triangles*12+j*16+8+v*2);
#undef HALF
 for(unsigned j=0;j<s.colours;j++){uint32_t v=out?model_get(p+s.colourOffset+j*4):model_get(in+at);if(out)model_put(out+at,v);else if(apply)model_put(p+s.colourOffset+j*4,v);at+=4;}if(at>PE_STATE_FIELD_MODEL_BYTES)return 0;if(!out)for(size_t j=at;j<PE_STATE_FIELD_MODEL_BYTES;j++)if(in[j])return 0;return 1;}
int PeFieldModel_Capture(const void*p,size_t n,unsigned char*out,size_t cap){return p&&out&&cap==PE_STATE_FIELD_MODEL_BYTES&&model_walk((unsigned char*)p,n,0,out,0);}
int PeFieldModel_Validate(const void*p,size_t n,const unsigned char*in,size_t bytes){return p&&in&&bytes==PE_STATE_FIELD_MODEL_BYTES&&model_walk((unsigned char*)p,n,in,0,0);}
int PeFieldModel_Restore(void*p,size_t n,const unsigned char*in,size_t bytes){return PeFieldModel_Validate(p,n,in,bytes)&&model_walk(p,n,in,0,1);}
