typedef struct ModelBinding{unsigned char*data;size_t available;uint32_t offset,extent,key;}ModelBinding;
static int model_overlap(uintptr_t a,size_t an,uintptr_t b,size_t bn){return an&&bn&&a<b+bn&&b<a+an;}
/* Full source spans, not merely pointer-start checks. The row grammar is
 * the original Anim_DecodeBoneRotations Byte/Short channel cursor advance. */
static int model_actor_span(const RenderObjectHeader*h,size_t available,size_t*bytes){if(available<sizeof*h)return 0;unsigned c[4]={h->packet34_count,h->packet28_count,h->packet24_count,h->packet1c_count},faces=0;for(unsigned j=0;j<4;j++)faces+=c[j];size_t n=sizeof*h+(size_t)h->part_count*sizeof(RenderObjectPart)+(size_t)h->vertex_count*12+(size_t)faces*sizeof(RenderPrimitiveDescriptor)+(3u+2u*h->part_count)*8+((h->matrix_command_bytes+3u)&~3u)+(size_t)c[0]*16+(size_t)c[1]*12;if(n>available)return 0;*bytes=n;return 1;}
static int model_animation_span(const unsigned char*p,size_t available,size_t*bytes){if(available<sizeof(RenderAnimationDataHeader))return 0;unsigned shortMode=(p[0]&3)==2,frames=p[2],bones=(unsigned)p[1]+1;size_t at=sizeof(RenderAnimationDataHeader);for(unsigned phase=0;phase<2;phase++){unsigned channels=phase?3*bones:3;size_t stride=phase&&!shortMode?((frames>>2)+1)*4:((frames>>1)+1)*4;for(unsigned j=0;j<channels;j++){unsigned markerBytes=phase&&!shortMode?1:2;if(at>available||markerBytes>available-at)return 0;int constant=markerBytes==1?p[at]!=0:model_half(p+at)!=0;size_t step=constant?4:stride;if(step>available-at)return 0;at+=step;}}*bytes=at;return 1;}
static int model_alias_source(const ModelBinding*b,const void*p,int animation){if(!p)return 1;unsigned id;uint32_t offset;size_t available;uint64_t epoch;if(!PeStateBankSource_Locate(p,1,&id,&offset,&available,&epoch))return 0;size_t bytes;if(animation){if(!model_animation_span(p,available,&bytes))return 0;}else if(!model_actor_span(p,available,&bytes))return 0;return !model_overlap((uintptr_t)b->data,b->extent,(uintptr_t)p,bytes);}
/* Parse the actual original keyEntries grammar without the unbounded retail
 * search helper. Record reserved00 is NOT guessed to be a payload size. */
static int model_bindings(ModelBinding out[3],uint32_t*room,uint64_t*epoch){PeScriptAsset asset;unsigned source;uint32_t rootOffset;size_t bytes;unsigned char*base=(unsigned char*)g_LoadedSceneAssetBlock[0];if(!room||!epoch||!PeStateAssets_Get(&asset)||!PeStateBankSource_Locate(base,8,&source,&rootOffset,&bytes,epoch)||source!=PE_STATE_BANK_ROOM||rootOffset)return 0;*room=asset.room;memset(out,0,3*sizeof*out);if(asset.room!=5&&asset.room!=23)return 1;uint32_t directory=model_get(base+4);if(directory%4||directory>bytes||52>bytes-directory)return 0;uint32_t descriptor=model_get(base+directory+8),table=descriptor&0x3fffff,count=descriptor>>22;if(table%4||table>bytes||count>(bytes-table)/12)return 0;const uint32_t keys[3]={0xC5462704u,0xC5862704u,0xC5463704u};for(unsigned k=0;k<3;k++){if((asset.room==5&&k==2)||(asset.room==23&&k!=2))continue;unsigned found=0;uint32_t offset=0;for(unsigned j=0;j<count;j++){const unsigned char*r=base+table+j*12;if(model_get(r+8)==keys[k]){if(found++)return 0;offset=model_get(r+4)&0xffffff;}}if(!found)continue;if(offset>bytes||16>bytes-offset||offset%4)return 0;size_t available=bytes-offset;for(unsigned j=0;j<count;j++){uint32_t other=model_get(base+table+j*12+4)&0xffffff;if(other>=bytes)return 0;if(other==offset&&model_get(base+table+j*12+8)!=keys[k])return 0;if(other>offset&&other-offset<available)available=other-offset;}ModelShape shape;if(!model_shape(base+offset,available,&shape))return 0;if(model_overlap(offset,shape.extent,directory,52)||model_overlap(offset,shape.extent,table,count*12))return 0;out[k]=(ModelBinding){base+offset,available,offset,shape.extent,keys[k]};}
 /* Before any mutable write, reject whole-model aliasing with another selected
  * model and every registered native actor model/row pointer. */
 for(unsigned k=0;k<3;k++)if(out[k].data){uintptr_t a=(uintptr_t)out[k].data;if(model_overlap(a,out[k].extent,(uintptr_t)asset.data,asset.bytes))return 0;for(unsigned j=0;j<k;j++)if(out[j].data&&model_overlap(a,out[k].extent,(uintptr_t)out[j].data,out[j].extent))return 0;for(unsigned j=0;j<10;j++){if(!model_alias_source(&out[k],g_GameState.bank_slots[j],0))return 0;for(unsigned r=0;r<48;r++)if(!model_alias_source(&out[k],g_GameState.bank_rows[j][r],1))return 0;}uint32_t liveSeen=0;unsigned visited=0;for(FieldActor*actor=g_FieldActorListHead;actor;actor=actor->next){unsigned id;for(id=0;id<14;id++)if(actor==&g_EntityPool[id])break;if(id==14||visited++>=14||(liveSeen&(1u<<id)))return 0;liveSeen|=1u<<id;if(!model_alias_source(&out[k],actor->model_state.model_header,0)||!model_alias_source(&out[k],actor->render_object.header,0))return 0;}}
 return 1;}
int PeFieldModels_Walk(const unsigned char*in,unsigned char*out,int apply){if((!in&&!out)||(out&&apply)||!PeStateBoundary_AtCpuPoint())return 0;if(apply&&(!Psyz_StateKernelOwned()||!Psyz_StateAudioOwned()||!PeFieldModels_Walk(in,0,0)))return 0;ModelBinding models[3];uint32_t room;uint64_t epoch;if(!model_bindings(models,&room,&epoch))return 0;if(out){memset(out,0,PE_STATE_FIELD_MODELS_BYTES);memcpy(out,"PEFMGR01",8);model_put(out+24,room);model_put(out+32,(uint32_t)epoch);model_put(out+36,(uint32_t)(epoch>>32));}else{if(memcmp(in,"PEFMGR01",8)||model_get(in+24)!=room||model_get(in+28)||model_get(in+32)!=(uint32_t)epoch||model_get(in+36)!=(uint32_t)(epoch>>32))return 0;for(unsigned j=40;j<128;j++)if(in[j])return 0;}
 uint16_t*params[4]={&g_FieldFxModelTpage,&g_FieldFxModelClut,&g_FieldFxModelSemiTrans,(uint16_t*)&g_FieldFxModelDepthBias};for(unsigned j=0;j<4;j++){uint32_t v=out?*params[j]:model_get(in+8+j*4);if(v>65535)return 0;if(out)model_put(out+8+j*4,v);else if(apply)*params[j]=(uint16_t)v;}for(unsigned j=0;j<256;j++){if(out)model_put(out+128+j*4,g_FieldModelColorBackup[j]);else if(apply)g_FieldModelColorBackup[j]=model_get(in+128+j*4);}
 for(unsigned k=0;k<3;k++){size_t at=128+1024+k*(64+PE_STATE_FIELD_MODEL_BYTES);ModelBinding*b=&models[k];if(!b->data){if(!out)for(size_t j=0;j<64+PE_STATE_FIELD_MODEL_BYTES;j++)if(in[at+j])return 0;continue;}uint32_t expected[4]={b->key,b->offset,b->extent,1};for(unsigned j=0;j<4;j++){if(out)model_put(out+at+j*4,expected[j]);else if(model_get(in+at+j*4)!=expected[j])return 0;}if(!out)for(unsigned j=16;j<64;j++)if(in[at+j])return 0;if(out){if(!PeFieldModel_Capture(b->data,b->available,out+at+64,PE_STATE_FIELD_MODEL_BYTES))return 0;}else if(!PeFieldModel_Validate(b->data,b->available,in+at+64,PE_STATE_FIELD_MODEL_BYTES))return 0;}
 if(apply)for(unsigned k=0;k<3;k++)if(models[k].data){size_t at=128+1024+k*(64+PE_STATE_FIELD_MODEL_BYTES);if(!PeFieldModel_Restore(models[k].data,models[k].available,in+at+64,PE_STATE_FIELD_MODEL_BYTES))return 0;}return 1;}

